params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $HOME 'HeavenBridgeRepo'
$origin=(git -C $relay remote get-url origin).Trim()
$tmp=Join-Path $env:TEMP ('runner-hardening-latest-main-'+[guid]::NewGuid().ToString('N'))
git clone --quiet $origin $tmp
if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
try {
  Set-Location $tmp
  git checkout --quiet fix/heaven-runner-single-session-20260929
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  git fetch --quiet origin main
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  $base=(git rev-parse origin/main).Trim()
  $head=(git rev-parse HEAD).Trim()
  git -c user.name='Heaven Verification' -c user.email='heaven-verification@local.invalid' merge --no-ff --no-edit origin/main
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  $merge=(git rev-parse HEAD).Trim()
  $script=Join-Path $tmp 'heaven-bridge\install-github-runner.ps1'
  $tokens=$null; $errors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($script,[ref]$tokens,[ref]$errors) | Out-Null
  if($errors.Count -gt 0){ $errors | ForEach-Object { Write-Error $_.Message }; exit 1 }
  python .\heaven-bridge\test_worker.py
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  python .\heaven-bridge\tests\test_worker.py
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  git diff --check origin/main...HEAD
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  Write-Output ('LATEST_MAIN='+$base)
  Write-Output ('PR_HEAD='+$head)
  Write-Output ('SYNTHETIC_MERGE='+$merge)
} finally {
  Set-Location $HOME
  Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
